$ErrorActionPreference = "Stop"

$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"

if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}

Write-Host "Installing MNTrapTeam single-shoot diagnostic..."

$payload = ""
[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\debug_shoot_cli.py"),
    [Convert]::FromBase64String($payload)
)

Set-Location $ProjectRoot

Write-Host "Checking syntax..."
& ".\.venv\Scripts\python.exe" -m py_compile ".\mntrapteam\debug_shoot_cli.py"
if ($LASTEXITCODE -ne 0) {
    throw "Syntax check failed."
}

Write-Host ""
Write-Host "Single-shoot diagnostic installed."
Write-Host ""
Write-Host "Run John Berning only:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.debug_shoot_cli 2117 --name LARSON'
Write-Host ""
Write-Host "Optional full CSV dump:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.debug_shoot_cli 2117 --name LARSON --dump ".\data\connector_downloads\john_berning_2117_rows.csv"'
